function generateUpdateBat(e,t){const n=["background.js","content.js","popup.js","popup.html","popup.css","popup-animations.css","manifest.json","config.js","logger.js","utils.js","max.js","shared/constants.js","update-generator.js"];let o="@echo off\nchcp 65001 >nul\n";o+=`set "EXT_FOLDER=${e}"\n`,o+=`set "BASE_URL=${t}"\n\n`,o+="echo Обновление расширения 1C Notification...\n\n";for(const s of n){const n=s.includes("/")?s.substring(0,s.lastIndexOf("/")):"";n&&(o+=`if not exist "${e}\\${n.replace("/","\\")}" mkdir "${e}\\${n.replace("/","\\")}"\n`),o+=`echo Downloading ${s}...\n`;const r=`${e}\\${s.replace("/","\\")}`;o+=`powershell -Command "try { $r = Invoke-WebRequest -Uri '${t}${s}' -ErrorAction Stop; if ($r.Content.Length -lt 100) { Write-Host 'FAIL: file too small'; exit 1 } [IO.File]::WriteAllBytes('${r}', $r.Content); Write-Host 'OK' } catch { Write-Host 'FAIL: $($_.Exception.Message)'; exit 1 }"\n`}return o+="\necho.\necho Обновление завершено! Перезагрузите расширение в chrome://extensions/\npause\n",o}window.generateUpdateBat=generateUpdateBat;